  xNoSource: ['Not applied: no contributing source recorded', 'No aplicada: no hay fuente registrada con aporte', 'Não aplicada: nenhuma fonte contribuinte registrada', 'Non appliquée : aucune source contributive enregistrée', 'Nicht angewendet: keine beteiligte Quelle erfasst'],
