  xPartial: ['Classes {u_c} on only {n} of {m} sources: partial', 'Clases {u_c} en solo {n} de {m} fuentes: parcial', 'Classes {u_c} em apenas {n} de {m} fontes: parcial', 'Classes {u_c} sur seulement {n} des {m} sources : partielle', 'Klassen {u_c} nur auf {n} von {m} Quellen: teilweise'],

