  gSurface: ['{t_s}. Estimated, not measured.', '{t_s}. Estimada, no medida.', '{t_s}. Estimada, não medida.', '{t_s}. Estimée, non mesurée.', '{t_s}. Geschätzt, nicht gemessen.'],
  seriesLabel: ['Derived surface ({u_p}th percentile of corridor returns)', 'Superficie derivada (percentil {u_p} de los retornos del corredor)', 'Superfície derivada (percentil {u_p} dos retornos do corredor)', 'Surface dérivée ({u_p}e centile des retours du corridor)', 'Abgeleitete Fläche ({u_p}. Perzentil der Korridorechos)'],
  gVertical: ['Vertical reference: {t_w}. {t_n}', 'Referencia vertical: {t_w}. {t_n}', 'Referência vertical: {t_w}. {t_n}', 'Référence verticale : {t_w}. {t_n}', 'Höhenbezug: {t_w}. {t_n}'],
  gProvenance: ['Provenance: {t_p}', 'Procedencia: {t_p}', 'Procedência: {t_p}', 'Provenance : {t_p}', 'Herkunft: {t_p}'],
  gNoProvenance: ['Provenance: no record of the sources read was attached to this export, so the contributing sources and the read scope are not recorded on this drawing.', 'Procedencia: esta exportación no lleva registro de las fuentes leídas, así que las fuentes y el alcance de la lectura no constan en este plano.', 'Procedência: esta exportação não traz registro das fontes lidas, portanto as fontes e o escopo da leitura não constam neste desenho.', "Provenance : aucun registre des sources lues n'accompagne cet export ; les sources et la portée de lecture ne figurent pas sur ce plan.", 'Herkunft: Diesem Export liegt kein Nachweis der gelesenen Quellen bei; Quellen und Leseumfang sind auf dieser Zeichnung nicht verzeichnet.'],
  gCoverage: ['Coverage: {t_c}. The profile is sampled from the points read, not the whole file.', 'Cobertura: {t_c}. El perfil se muestrea de los puntos leídos, no del archivo completo.', 'Cobertura: {t_c}. O perfil é amostrado dos pontos lidos, não do arquivo inteiro.', 'Couverture : {t_c}. Le profil est échantillonné sur les points lus, pas sur le fichier entier.', 'Abdeckung: {t_c}. Das Profil stammt aus den gelesenen Punkten, nicht aus der ganzen Datei.'],
